async () => {
  // Find Monday 7pm Open Gym sessions (09:00 UTC = 7pm AEST)
  const r = await fetch('/graphql', { method: 'POST', headers: {'Content-Type': 'application/json'}, credentials: 'include',
    body: JSON.stringify({ query: `{ classes(from: "2026-08-17T00:00:00+10:00", to: "2026-09-15T00:00:00+10:00") { id classType startsAt spotsLeft confirmedCount capacity } }` })
  });
  const data = await r.json();
  // Filter for Monday open_gym at 09:00 UTC (7pm AEST)
  const mondayOpenGyms = data.data.classes.filter(c => {
    const d = new Date(c.startsAt);
    return c.classType === 'open_gym' && d.getUTCDay() === 1 && d.getUTCHours() === 9;
  });
  return JSON.stringify(mondayOpenGyms, null, 2);
}

