    "7b45cf15-91ed-5eb9-bbc1-6f3c1424513f"   // Sep 14
  ];
  const results = [];
  for (const id of ids) {
    const r = await fetch('/graphql', { method: 'POST', headers: {'Content-Type': 'application/json'}, credentials: 'include',
      body: JSON.stringify({ query: `mutation { createReservation(classInstanceId: "${id}") { reservation { id status waitlistPosition classInstance { startsAt spotsLeft } } errorCode } }` })
    });
    const data = await r.json();
    results.push({ classInstanceId: id, result: data.data.createReservation });
  }
  return JSON.stringify(results, null, 2);
}

